      medium: [
        { id: 'tariq_rel_med_01', arabic: 'رفيقي! — المثل: الرفيق قبل الطريق — وأنت رفيق طيب', english: 'My companion! — proverb: the companion before the road — and you are a good companion', transliteration: 'rafiqi! — al-mathal: ar-rafiq qabl at-tariq — wa-anta rafiq tayyib', minRelationship: 30 },
        { id: 'tariq_rel_med_02', arabic: 'أنت تستمع وتتعلم — هذا أكبر مزايا الشاب الحكيم', english: 'You listen and learn — this is the greatest quality of a wise young person', transliteration: 'anta tustami\' wa-ta\'allam — hadha akbar mazaya ash-shabb al-hakim', minRelationship: 30 },
        { id: 'tariq_rel_med_03', arabic: 'أُهدي لك مجموعة أمثال جمعتُها — أمانة الأجداد في يدك', english: 'I give you a collection of proverbs I gathered — the ancestors\' trust is in your hands', transliteration: 'uhdi laka majmu\'at amthal jama\'tuha — amanat al-ajdad fi yadik', minRelationship: 30 },
        { id: 'tariq_rel_med_04', arabic: 'أنت تقدّر الحكمة — هذا جعلك مختلفاً عن كثيرين', english: 'You appreciate wisdom — this makes you different from many', transliteration: 'anta tuqaddir al-hikma — hadha ja\'alaka mukhtalifan \'an kathirin', minRelationship: 30 },
        { id: 'tariq_rel_med_05', arabic: 'رفقتك تُذكرني بصديق قديم — المثل: الأصدقاء الحقيقيون كالنجوم', english: 'Your company reminds me of an old friend — proverb: true friends are like stars', transliteration: 'rifqatuka tudhakkiruni bi-sadiq qadim — al-mathal: al-asdiqa\' al-haqiqiyyun kan-nujum', minRelationship: 30 },
      ],
      high: [
        { id: 'tariq_rel_high_01', arabic: 'أنت كابني في الروح والحكمة — أعلّمك ما لم أُعلمه الآخرين', english: 'You are like my son in spirit and wisdom — I teach you what I have not taught others', transliteration: 'anta ka-ibni fi ar-ruh wal-hikma — u\'allimuka ma lam u\'alimhu al-akharin', minRelationship: 70 },
        { id: 'tariq_rel_high_02', arabic: 'أريدك أن تحمل هذه الأمثال للأجيال القادمة — مسؤولية', english: 'I want you to carry these proverbs to coming generations — a responsibility', transliteration: 'uridu an tahmal hadhihi al-amthal lil-ajyal al-qadima — mas\'uliyya', minRelationship: 70 },
        { id: 'tariq_rel_high_03', arabic: 'أنت الشخص الوحيد الذي أُسلّمه كنز الأمثال النادرة', english: 'You are the only person to whom I entrust the treasure of rare proverbs', transliteration: 'anta ash-shakhss al-wahid alladhi usallimuh kanz al-amthal an-nadira', minRelationship: 70 },
        { id: 'tariq_rel_high_04', arabic: 'صداقتك أثبتت أن المثل صادق: رب أخ لم تلده أمك', english: 'Your friendship proved the proverb true: many a brother was not born of your mother', transliteration: 'sadaqatuk athbatat anna al-mathal sadiq: rabb akh lam talidhu ummuk', minRelationship: 70 },
        { id: 'tariq_rel_high_05', arabic: 'حين أرحل — ستحمل أنت الأمانة — وهذا أعظم ما أتمناه', english: 'When I pass — you will carry the trust — and this is the greatest thing I could wish for', transliteration: 'hin arhal — satahmal anta al-amana — wa-hadha a\'dham ma atamannahu', minRelationship: 70 },
      ],
